        new Quote { Id = "https://en.wikiquote.org/wiki/Ravi_Shankar_%28spiritual_leader%29", Text = "Mind without agitation is meditation. Mind in the present moment is meditation. Mind that has no hesitation, no anticipation is meditation. Mind that has come back home, to the source, is meditation. Mind that becomes ‘‘no mind’’ is meditation.", Author = "Ravi Shankar (spiritual leader)" },
