        new Quote { Id = "https://en.wikiquote.org/wiki/Axel_Honneth", Text = "Social philosophy is primarily concerned with determining and discussing processes of social decelopment that can be viewed as misdevelopments, disorders or social pathologies.", Author = "Axel Honneth" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Judith_Peace_Achan", Text = "UWA is currently installing wooden poles, some of which are reused, while others have developed cracks. We would prefer them to install concrete poles instead, as this would demonstrate the government's commitment to a durable, long-term solution to the human-wildlife conflict in the district.", Author = "Judith Peace Achan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Walter_P._Stacy", Text = "It would be almost unbelievable, if history did not record the tragic fact, that men have gone to war and cut each other's throats because they could not agree as to what was to become of them after their throats were cut.", Author = "Walter P. Stacy" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Thaddeus_McCotter", Text = "They’re trying to keep the populists of both left and right apart with cultural issues, and they’re doing it to insulate themselves from any combination or constituency that can come after their power, perks and wealth. They’re dividing and conquering.", Author = "Thaddeus McCotter" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Camillus_Archibong_Etokudoh", Text = "We try to educate the people as a Christian community. We have meetings and prayer time together. In this way, we do not judge things in terms of majority or minority in relationship to the other Christian denominations, because we work together so that all Christians may be one.", Author = "Camillus Archibong Etokudoh" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Merry_Wives_of_Windsor", Text = "I will make a Star Chamber matter of it.", Author = "The Merry Wives of Windsor" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Claude_Traunecker", Text = "The Egyptians felt no need to establish an inventory of their gods. The efforts of the Hittites, who compiled laborious concordance lists matching their gods with those of their neighbors, must have made them smile.", Author = "Claude Traunecker" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Vince_Young", Text = "My mom said 'you are either going to be in jail, or be killed'. So I decided to do something different because I didn't want to be in one of those positions, so I kind of focused on football and took off from there.", Author = "Vince Young" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Hubert_Selby%2C_Jr.", Text = "Sometimes we have the absolute certainty there's something inside us that's so hideous and monstrous that if we ever search it out we won't be able to stand looking at it. But it's when we're willing to come face to face with that demon that we face the angel.", Author = "Hubert Selby, Jr." },
        new Quote { Id = "https://en.wikiquote.org/wiki/Sunkanmi_Omobolanle", Text = "You just have to be very good at what you do.", Author = "Sunkanmi Omobolanle" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Charisma_Carpenter", Text = "On a highway in a moving automobile. I wasn't driving. It worked out quite well, but I don't know how it did. I was young and stupid.", Author = "Charisma Carpenter" },
