        new Quote { Id = "https://en.wikiquote.org/wiki/Jim_Henson", Text = "I suppose that he's an alter ego. But he's a little snarkier than I am - slightly wise. Kermit says things I hold myself back from saying.", Author = "Jim Henson" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Shitsama_Nyamweya", Text = "When I was studying neurosurgery, I didn't have any women role models to look up to or approach for advice. This was a major challenge. That's why I want to be there for others now. I want them to know that if I did it, they also can.", Author = "Shitsama Nyamweya" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nashville_sound", Text = "The Nashville sound – where traditional instruments like pedal steel guitar and violin were phased out in favor of strings and background vocals -- had more in common with mainstream ‘50s vocal pop than Western swing or rockabilly.", Author = "Nashville sound" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Valerie_Solanas", Text = "Life in this society being, at best, an utter bore and no aspect of society being at all relevant to women, there remains to civic-minded, responsible, thrill-seeking females only to overthrow the government, eliminate the money system, institute complete automation and eliminate the male sex.", Author = "Valerie Solanas" },
        new Quote { Id = "https://en.wikiquote.org/wiki/White_Zombie_%28film%29", Text = "Neil Parker: Looks like a burial.\nMadeline: In the road?", Author = "White Zombie (film)" },
