        new Quote { Id = "https://en.wikiquote.org/wiki/Mohammed_Salisu", Text = "If it rains, the game will be faster, but I don’t think we should focus on that. We simply need to concentrate on the match, because we know it’s a very important game for us.", Author = "Mohammed Salisu" },
