        new Quote { Id = "https://en.wikiquote.org/wiki/Shakugan_no_Shana", Text = "Alastor: A heartbeat that lasts for eternity. Lives consumed in soundless balls of fire. No one can tell when the world is displaced and the Flames of the Crimson World sweep over all.", Author = "Shakugan no Shana" },
