        new Quote { Id = "https://en.wikiquote.org/wiki/Richard_Hunt", Text = "A sculptor can be thought of as the sort of person who can reduce impressions of things, responses, and ideas about things into sculptural forms.", Author = "Richard Hunt" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Genevieve_Cogman", Text = "The atmosphere of the place soothed her automatically; the rich lantern-lights, the sheer scent of paper and leather, and the fact that everywhere she looked, there were books, books, beautiful books.", Author = "Genevieve Cogman" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Buck_Privates_Come_Home", Text = "Bill Gregory: That's my car, hey Slick, who's racing my car?\nSlicker Smith: I don't know, I'll ask Herbie... Herbie? Herbie can't drive!", Author = "Buck Privates Come Home" },
