        new Quote { Id = "https://en.wikiquote.org/wiki/Pamela_Nomvete", Text = "My self-esteem was rock bottom and sinking. Slowly‚ I was just being broken down. Everything was going out and nothing was going in. I wasn’t nurturing Pamela. By the time my partner decided to move his whole family into my house‚ Pamela was gone and I was asking myself who am I?", Author = "Pamela Nomvete" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Lafcadio_Hearn", Text = "How sweet Japanese woman is! All the possibilities of the race for goodness seem to be concentrated in her.", Author = "Lafcadio Hearn" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Fumio_Kishida", Text = "Russia's actions (in attacking Ukraine) very clearly damage Ukraine's sovereignty and go against international law. We once again criticize these moves and strongly urge Russia to return to diplomatic discussions. Should the situation worsen, we'll move quickly to take further action.", Author = "Fumio Kishida" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Syndicate_Wars", Text = "A hundred elephants can wreck the outer walls of a fortress. One diseased rat can kill all those inside.", Author = "Syndicate Wars" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jos%C3%A9_Luis_Mollaghan", Text = "Mary places herself between her Son and mankind in the reality of our hardships and sufferings. She places herself in the middle - she becomes a mediator not as a stranger, but in her role as true mother, aware that as such she makes present to her Son the needs of mankind.", Author = "José Luis Mollaghan" },
        new Quote { Id = "https://en.wikiquote.org/wiki/War_%28film%29", Text = "Vengeance is the ultimate weapon.", Author = "War (film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Filth_and_Wisdom", Text = "You know, in my country there is a saying: If you want to reach the sky - fuck a duck and try to fly.", Author = "Filth and Wisdom" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Tomorrow_We_Live_%281942_film%29", Text = "William Pop Bronson: Where you going?\nJulie Bronson: I don't know.\nWilliam Pop Bronson: Julie sit down and finish your dinner, this is no way to carry on about nothing at all.", Author = "Tomorrow We Live (1942 film)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Julia_Caroline_Dorr", Text = "O golden Silence, bid our souls be still,And on the foolish fretting of our careLay thy soft touch of healing unaware!", Author = "Julia Caroline Dorr" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Judas_Iscariot", Text = "Why was not this ointment sold for three hundred pence, and given to the poor?", Author = "Judas Iscariot" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Starik_Khottabych", Text = "Earth is of the form of a plain disk that is washed around by the Grand River called The Ocean.", Author = "Starik Khottabych" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Joseph_Henderson_%28pilot%29", Text = "Joseph Henderson, one of the oldest, wealthiest, and most widely known pilots in the New York Sandy Hook service, died yesterday of peritonitis at his home in Brooklyn.", Author = "Joseph Henderson (pilot)" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Declaration_of_the_Rights_of_Man_and_of_the_Citizen", Text = "Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l'utilité commune.", Author = "Declaration of the Rights of Man and of the Citizen" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Juan_de_Zum%C3%A1rraga", Text = "The business ability of the bishop assisted somewhat to temper his zeal in certain directions, and to guide his labors as administrator and head of the church, whose interest he ably promoted.", Author = "Juan de Zumárraga" },
        new Quote { Id = "https://en.wikiquote.org/wiki/James_S._A._Corey", Text = "Writing science fiction is a race between the author's imagination and the progress of science and history. Fiction is always on the losing end; the question is only how fast.", Author = "James S. A. Corey" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Godfather", Text = "[to Bonasera] I want you to use all your powers, and all your skills. I don't want his mother to see him this way. [looks in anguish at Sonny's bullet-ridden body] Look how they massacred my boy!", Author = "The Godfather" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Jane_Egerton-Idehen", Text = "I prayed for it, and I certainly wanted it. Like any goal, you give it your all, even though there’s never a guarantee of the outcome.", Author = "Jane Egerton-Idehen" },
