        new Quote { Id = "https://en.wikiquote.org/wiki/Arctic", Text = "Even in our day, science suspects beyond the Polar seas, at the very circle of the Arctic Pole, the existence of a sea which never freezes and a continent which is ever green.", Author = "Arctic" },
        new Quote { Id = "https://en.wikiquote.org/wiki/Nana_Darkoa_Sekyiamah", Text = "We achieve freedom when we let go of the weight of societal expectations, and when we find our people – those who love us, care for us, and hold us up when we start slipping.", Author = "Nana Darkoa Sekyiamah" },
        new Quote { Id = "https://en.wikiquote.org/wiki/The_Animal", Text = "Now that's some good badger milk.", Author = "The Animal" },
